import { GrandTestQuestion } from "./grandTestMeta";

// FREE Live Mock Test — 28th June 2026. 100 questions across all 17 subjects
// + General Agriculture. 30 special-format items (Assertion-Reason, matching
// columns, True/False); the rest direct MCQs. Source-grounded; no repeats from
// the 8-June (gt11) or 19-June (gt12) live papers.
export const GRAND_TEST_13: GrandTestQuestion[] = [
  { id:"gt13_001", qNo:1, subject:"agronomy", question:"Assertion (A): Conservation tillage is recommended for sustainable dryland farming.\nReason (R): Conservation tillage retains at least 30% of crop residue on the soil surface, which checks erosion and conserves soil moisture.", options:["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true but R is false", "A is false but R is true"], correct:0, explanation:"By definition conservation tillage leaves ≥30% residue cover on the surface after sowing. This cover reduces runoff and erosion and conserves moisture — which is exactly why it suits dryland farming. Hence R correctly explains A." },
  { id:"gt13_002", qNo:2, subject:"agronomy", question:"In most annual field crops, the critical period of crop–weed competition lies in the:", options:["First one-third of the crop's life cycle", "Maturity and ripening phase only", "Last 15 days before harvest", "Entire duration of the crop equally"], correct:0, explanation:"Weeds cause maximum yield loss when they compete during the first one-third of the crop period (early vegetative stage). Keeping the field weed-free during this critical period is enough to prevent most of the competition loss." },
  { id:"gt13_003", qNo:3, subject:"agronomy", question:"Match List-I (Cropping concept) with List-II (Meaning) and choose the correct combination:", matchTable:{ headers:["List-I (Concept)", "List-II (Meaning)"], rows:[["A. Cropping intensity", "1. Raising a crop from the stubble regrowth of the previous crop"], ["B. Ratoon cropping", "2. Growing crops in between rows of planted trees/shrubs"], ["C. Alley cropping", "3. Number of crops grown on the same land in a year, expressed as a percentage"], ["D. Relay cropping", "4. Sowing the succeeding crop before harvesting the standing crop"]] }, options:["A-3, B-1, C-2, D-4", "A-4, B-1, C-2, D-3", "A-1, B-3, C-2, D-4", "A-3, B-2, C-1, D-4"], correct:0, explanation:"Cropping intensity = number of crops per year ×100 (3); Ratoon = crop from stubble regrowth (1); Alley cropping = crops between tree rows (2); Relay = next crop sown into the standing crop (4). Hence A-3, B-1, C-2, D-4." },
  { id:"gt13_004", qNo:4, subject:"agronomy", question:"Consider the following statements and identify the correct ones:\n1. Green manuring increases soil organic matter and improves soil structure.\n2. Puddling in lowland rice increases the percolation loss of water.\n3. A stubble mulch conserves soil moisture by reducing evaporation.", options:["1 and 3 only", "1 and 2 only", "1, 2 and 3", "2 and 3 only"], correct:0, explanation:"Statements 1 and 3 are correct. Statement 2 is FALSE — puddling DECREASES percolation by forming a compact low-permeability layer, which is why it is done for lowland rice. Hence 1 and 3 only." },
  { id:"gt13_005", qNo:5, subject:"agronomy", question:"The ratio of the weight of water transpired by a crop to the weight of dry matter produced is termed the:", options:["Delta of the crop", "Field capacity", "Transpiration ratio", "Consumptive use"], correct:2, explanation:"The transpiration ratio is the units of water transpired to produce one unit of dry matter. A low transpiration ratio indicates higher water-use efficiency (e.g., sorghum/bajra are efficient C4 crops)." },
  { id:"gt13_006", qNo:6, subject:"kharif-crops", question:"Among all cereals, the crop with the highest productivity and photosynthetic efficiency (a C4 plant) is:", options:["Maize", "Barley", "Rice", "Wheat"], correct:0, explanation:"Maize is a C4 plant with the highest productivity among grain crops. Its Hatch–Slack pathway concentrates CO2 in bundle-sheath cells, suppressing photorespiration and giving high efficiency at high light and temperature." },
  { id:"gt13_007", qNo:7, subject:"kharif-crops", question:"Sorghum (jowar) is popularly known as:", options:["Finger millet", "Foxtail millet", "Great millet", "Pearl millet"], correct:2, explanation:"Sorghum (Sorghum bicolor) is called 'great millet'. It is a hardy, drought-tolerant kharif cereal and a staple food in parts of Asia and Africa; its stalks are widely used as cattle fodder." },
  { id:"gt13_008", qNo:8, subject:"kharif-crops", question:"Assertion (A): Soybean is called the 'Golden Bean'.\nReason (R): Soybean seed contains about 40% high-quality protein and about 20% oil, with a vast multiplicity of uses.", options:["A is true but R is false", "Both A and R are true, but R is NOT the correct explanation of A", "A is false but R is true", "Both A and R are true, and R is the correct explanation of A"], correct:3, explanation:"Soybean (Glycine max) earns the title 'Golden Bean' precisely because of its high protein (~40%) and oil (~20%) content and many uses. R correctly explains A." },
  { id:"gt13_009", qNo:9, subject:"kharif-crops", question:"Aerobic rice is best described as rice that is:", options:["Raised only under the SRI square-planting system", "Grown in non-puddled, aerobic soil like an upland crop", "Transplanted at 60-day seedling age", "Grown in continuously flooded, puddled fields"], correct:1, explanation:"Aerobic rice is grown in non-puddled, non-flooded (aerobic) soil like an irrigated upland crop, with a higher seed rate (25–30 kg/acre). It saves water compared with conventional transplanted puddled rice." },
  { id:"gt13_010", qNo:10, subject:"kharif-crops", question:"Which of the following statements about the SRI method of rice cultivation are correct?\n1. It uses very young seedlings (about 8–12 days old).\n2. Single seedlings are planted per hill at wide spacing.\n3. It requires more seed than the conventional transplanting method.", options:["1, 2 and 3", "1 and 2 only", "2 and 3 only", "1 and 3 only"], correct:1, explanation:"Statements 1 and 2 are correct. Statement 3 is FALSE — SRI uses far LESS seed (about 2 kg/acre) because single young seedlings are planted at wide spacing. Hence 1 and 2 only." },
  { id:"gt13_011", qNo:11, subject:"rabi-crops", question:"Groundnut is botanically unique among major oilseeds because:", options:["Its flowers are borne underground", "Its seeds have no testa", "It fixes atmospheric nitrogen in aerial nodules along its stem", "The peg grows into the soil so pods mature underground (geocarpy)"], correct:3, explanation:"Groundnut shows geocarpy — the flower is aerial, but after fertilisation the gynophore (peg) elongates and pushes the developing ovary into the soil, where the pod matures underground." },
  { id:"gt13_012", qNo:12, subject:"rabi-crops", question:"The approximate oil content of sesame (til) seed is:", options:["About 35%", "About 50%", "About 20%", "About 70%"], correct:1, explanation:"Sesame seed contains about 50% oil, the highest among the common edible oilseeds. Groundnut has about 45-50% and sunflower about 48-50%." },
  { id:"gt13_013", qNo:13, subject:"rabi-crops", question:"Castor is grown mainly as a commercial oilseed because its oil is:", options:["A non-edible industrial oil (ricinoleic acid)", "A premium edible cooking oil for daily use", "Used only as biofuel", "Identical to groundnut oil"], correct:0, explanation:"Castor oil is a non-edible industrial oil rich in ricinoleic acid, used in lubricants, paints, soaps and pharmaceuticals — hence castor is grown as a commercial (non-edible) oilseed." },
  { id:"gt13_014", qNo:14, subject:"rabi-crops", question:"In sugarcane cultivation, a 'ratoon crop' refers to:", options:["A crop raised from sets after deep ploughing", "The crop that regrows from cane stubble after harvest", "A crop grown only from seed-fluff", "An intercrop grown with the main cane"], correct:1, explanation:"A ratoon is the crop that regrows from the stubble/underground buds left after harvesting the plant cane. Ratooning saves planting cost and time, though yields decline after a few ratoons." },
  { id:"gt13_015", qNo:15, subject:"rabi-crops", question:"Which of the following statements is/are correct about cotton?\n1. Cotton lint (fibre) develops as epidermal hairs on the seed coat.\n2. In India cotton is grown mainly on black cotton (regur) soils.\n3. Cotton bolls in India are mostly harvested by hand picking.", options:["1 only", "1, 2 and 3", "2 and 3 only", "1 and 2 only"], correct:1, explanation:"All three are correct. Lint is made of seed-coat epidermal hairs; cotton thrives on black cotton soils; and in India bolls are largely hand-picked to maintain quality. Hence 1, 2 and 3." },
  { id:"gt13_016", qNo:16, subject:"genetics", question:"The Chromosome Theory of heredity — a fundamental unifying theory linking chromosome behaviour with the inheritance of traits — was proposed by:", options:["Charles Darwin", "Gregor Mendel", "Sutton and Boveri", "Hugo de Vries"], correct:2, explanation:"Sutton and Boveri (1902) proposed the Chromosome Theory, a fundamental unifying theory connecting chromosomes with heredity. Mendel gave the laws of inheritance, Darwin proposed natural selection, and de Vries described mutations." },
  { id:"gt13_017", qNo:17, subject:"genetics", question:"The method of isolating the progeny of a single homozygous plant from a self-pollinated crop is called:", options:["Backcross method", "Mutation breeding", "Pure line selection", "Mass selection"], correct:2, explanation:"Pure line selection isolates the progeny of a single homozygous self-pollinated plant (a pure line). Mass selection, in contrast, bulks many similar plants chosen on phenotype." },
  { id:"gt13_018", qNo:18, subject:"genetics", question:"Assertion (A): Hybrid vigour (heterosis) is exploited commercially in cross-pollinated crops like maize.\nReason (R): Heterosis is the superiority of the F1 hybrid over both its parents in vigour, yield or other traits.", options:["Both A and R are true, but R is NOT the correct explanation of A", "A is false but R is true", "A is true but R is false", "Both A and R are true, and R is the correct explanation of A"], correct:3, explanation:"Heterosis is the F1's superiority over both parents. Because this advantage is maximal in the F1 and crossing is easy in cross-pollinated crops like maize, hybrid vigour is commercially exploited there. R correctly explains A." },
  { id:"gt13_019", qNo:19, subject:"genetics", question:"In a self-pollinated crop, the natural mode of reproduction keeps the population:", options:["Highly heterozygous", "Genetically identical to wild relatives", "Always polyploid", "Largely homozygous (true-breeding lines)"], correct:3, explanation:"Self-pollination leads to homozygosity, so self-pollinated crops (rice, wheat, groundnut) consist of largely homozygous, true-breeding pure lines. Cross-pollinated crops, in contrast, are highly heterozygous." },
  { id:"gt13_020", qNo:20, subject:"seed-technology", question:"Which of the following statements about seed certification is/are correct?\n1. Breeder seed is the source of all subsequent seed classes.\n2. Foundation seed is produced from breeder seed.\n3. Certified seed tags are blue in colour in India.", options:["1 only", "1, 2 and 3", "1 and 2 only", "2 and 3 only"], correct:1, explanation:"All three are correct. The seed chain is Breeder → Foundation → Certified seed. In India the certified seed tag is blue, foundation seed tag is white, and breeder seed tag is golden yellow. Hence 1, 2 and 3." },
  { id:"gt13_021", qNo:21, subject:"entomology", question:"In the class Insecta, the body is divided into three regions and bears:", options:["Four pairs of legs and no antennae", "Two pairs of legs and one pair of antennae", "Three pairs of legs and two pairs of antennae", "Three pairs of legs and one pair of antennae"], correct:3, explanation:"Insects have the body divided into head, thorax and abdomen, with three pairs of legs (hexapoda) borne on the thorax and a single pair of antennae on the head. This distinguishes them from arachnids (4 pairs of legs)." },
  { id:"gt13_022", qNo:22, subject:"entomology", question:"Match List-I (Insect) with List-II (Type of mouthparts):", matchTable:{ headers:["List-I (Insect)", "List-II (Mouthparts)"], rows:[["A. Grasshopper", "1. Siphoning type"], ["B. Butterfly", "2. Sponging type"], ["C. Housefly", "3. Biting and chewing type"], ["D. Mosquito", "4. Piercing and sucking type"]] }, options:["A-1, B-3, C-2, D-4", "A-4, B-1, C-2, D-3", "A-3, B-2, C-1, D-4", "A-3, B-1, C-2, D-4"], correct:3, explanation:"Grasshopper = biting & chewing (3); Butterfly/moth = siphoning (1); Housefly = sponging (2); Mosquito = piercing & sucking (4). Hence A-3, B-1, C-2, D-4." },
  { id:"gt13_023", qNo:23, subject:"entomology", question:"Assertion (A): The honey bee is regarded as a beneficial insect.\nReason (R): Besides yielding honey and wax, it is an important pollinator of many crops.", options:["Both A and R are true, but R is NOT the correct explanation of A", "Both A and R are true, and R is the correct explanation of A", "A is true but R is false", "A is false but R is true"], correct:1, explanation:"The honey bee is beneficial because it pollinates crops (raising yields) and yields honey and wax. R correctly explains why A is true." },
  { id:"gt13_024", qNo:24, subject:"entomology", question:"The Economic Threshold Level (ETL) of a pest is the:", options:["Density at which control measures are taken to prevent economic injury", "Pest density at which the entire crop is completely and irreversibly destroyed", "Pest density that causes no measurable damage", "Highest pest density ever recorded in a field"], correct:0, explanation:"ETL is the pest population density at which control measures should be initiated to prevent the increasing pest population from reaching the Economic Injury Level (EIL) — the lowest density that causes economic damage." },
  { id:"gt13_025", qNo:25, subject:"entomology", question:"Which of the following statements about insect metamorphosis is/are correct?\n1. Complete metamorphosis has egg, larva, pupa and adult stages.\n2. In incomplete metamorphosis the immature stage is called a nymph.\n3. Grasshoppers undergo complete metamorphosis.", options:["1, 2 and 3", "1 and 2 only", "2 and 3 only", "1 and 3 only"], correct:1, explanation:"Statements 1 and 2 are correct. Statement 3 is FALSE — grasshoppers show INCOMPLETE (gradual) metamorphosis (egg → nymph → adult). Insects like butterflies and beetles show complete metamorphosis. Hence 1 and 2 only." },
  { id:"gt13_026", qNo:26, subject:"plant-pathology", question:"The 'disease triangle' that must coincide for a plant disease to develop consists of:", options:["Bacteria, fungi and viruses", "High temperature, humidity, rainfall and light intensity only", "A susceptible host, virulent pathogen and favourable environment", "Soil, water and air"], correct:2, explanation:"Disease develops only when three components coincide — a susceptible host, a virulent pathogen, and a favourable environment. Removing or weakening any one of the three checks the disease." },
  { id:"gt13_027", qNo:27, subject:"plant-pathology", question:"Match List-I (Disease) with List-II (Causal organism):", matchTable:{ headers:["List-I (Disease)", "List-II (Causal organism)"], rows:[["A. Late blight of potato", "1. Xanthomonas (bacterium)"], ["B. Bacterial leaf blight of rice", "2. Tobacco mosaic virus"], ["C. Mosaic of tobacco", "3. Phytophthora infestans (fungus-like)"], ["D. Rust of wheat", "4. Puccinia species (fungus)"]] }, options:["A-4, B-1, C-2, D-3", "A-3, B-1, C-2, D-4", "A-1, B-3, C-2, D-4", "A-3, B-2, C-1, D-4"], correct:1, explanation:"Late blight of potato = Phytophthora infestans (3); Bacterial leaf blight of rice = Xanthomonas oryzae (1); Tobacco mosaic = TMV (2); Wheat rust = Puccinia (4). Hence A-3, B-1, C-2, D-4." },
  { id:"gt13_028", qNo:28, subject:"plant-pathology", question:"Assertion (A): Bordeaux mixture is a widely used protective fungicide.\nReason (R): It is prepared by combining copper sulphate with lime in water.", options:["A is true but R is false", "Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is false but R is true"], correct:2, explanation:"Both statements are true, but R does NOT explain A. Bordeaux mixture IS made from copper sulphate + lime (R), but its fungicidal action is due to the toxic copper ions released — not merely because it is a mixture. So R is a true composition fact, not the explanation of its fungicidal nature." },
  { id:"gt13_029", qNo:29, subject:"plant-pathology", question:"Koch's postulates are a set of criteria used mainly to:", options:["Classify insects", "Measure soil fertility", "Prove a microbe causes a specific disease", "Estimate crop water requirement"], correct:2, explanation:"Koch's postulates establish a causal relationship between a microbe and a disease: the pathogen must be present in diseased plants, isolated in pure culture, reproduce the disease on inoculation, and be re-isolated from the inoculated host." },
  { id:"gt13_030", qNo:30, subject:"plant-pathology", question:"Which of the following statements is/are correct?\n1. Fungi have a cell wall made mainly of chitin.\n2. Viruses are obligate parasites that multiply only inside living host cells.\n3. Bacteria are killed by fungicides such as Bordeaux mixture.", options:["1 and 2 only", "2 and 3 only", "1 and 3 only", "1, 2 and 3"], correct:0, explanation:"Statements 1 and 2 are correct. Statement 3 is FALSE — fungicides act on fungi; bacterial diseases are managed with bactericides/antibiotics (e.g., streptocycline), not ordinary fungicides. Hence 1 and 2 only." },
  { id:"gt13_031", qNo:31, subject:"crop-pests", question:"The symptoms 'dead heart' in the vegetative stage and 'white ear head' at the panicle stage of rice are caused by the:", options:["Brown plant hopper", "Rice hispa", "Gall midge", "Yellow stem borer"], correct:3, explanation:"The yellow stem borer bores into the stem; in the vegetative stage the central whorl dries forming a 'dead heart', and at the reproductive stage the panicle dries to a chaffy white 'white ear head'." },
  { id:"gt13_032", qNo:32, subject:"crop-pests", question:"Assertion (A): Bt cotton is effective in controlling bollworms.\nReason (R): Bt cotton carries Cry genes from the bacterium Bacillus thuringiensis that express an insecticidal crystal protein toxic to bollworm larvae.", options:["A is true but R is false", "Both A and R are true, and R is the correct explanation of A", "A is false but R is true", "Both A and R are true, but R is NOT the correct explanation of A"], correct:1, explanation:"Bt cotton expresses the Cry (e.g., Cry1Ac) insecticidal protein from Bacillus thuringiensis, which is toxic to bollworm larvae on feeding. This is precisely why it controls bollworms, so R correctly explains A." },
  { id:"gt13_033", qNo:33, subject:"crop-pests", question:"Match List-I (Pest) with List-II (Host crop):", matchTable:{ headers:["List-I (Pest)", "List-II (Host crop)"], rows:[["A. Pink bollworm", "1. Rice"], ["B. Brown plant hopper", "2. Sorghum"], ["C. Shoot fly", "3. Cotton"], ["D. Pod borer (Helicoverpa)", "4. Redgram/chickpea"]] }, options:["A-3, B-2, C-1, D-4", "A-4, B-1, C-2, D-3", "A-1, B-3, C-2, D-4", "A-3, B-1, C-2, D-4"], correct:3, explanation:"Pink bollworm = cotton (3); Brown plant hopper = rice (1); Shoot fly = sorghum (2); Pod borer Helicoverpa armigera = redgram/chickpea (4). Hence A-3, B-1, C-2, D-4." },
  { id:"gt13_034", qNo:34, subject:"crop-pests", question:"In Integrated Pest Management (IPM), the use of natural enemies such as parasitoids and predators against pests is called:", options:["Biological control", "Mechanical control", "Cultural control", "Chemical control"], correct:0, explanation:"Biological control uses living natural enemies — parasitoids (e.g., Trichogramma), predators (e.g., ladybird beetle) and pathogens (e.g., NPV) — to suppress pest populations, a key non-chemical component of IPM." },
  { id:"gt13_035", qNo:35, subject:"soil-science", question:"Which soil separate has the greatest surface area per unit mass and the highest water-holding capacity?", options:["Sand", "Gravel", "Clay", "Silt"], correct:2, explanation:"Clay particles (<0.002 mm) are the finest soil separate with the largest specific surface area, giving high water- and nutrient-holding capacity and high plasticity. Sandy soils, being coarse, hold the least water." },
  { id:"gt13_036", qNo:36, subject:"soil-science", question:"Clay soils have a high cation exchange capacity (CEC) mainly because clay particles have:", options:["A very low surface area", "A coarse texture and a positive charge", "No charge at all", "A large surface area and a net negative charge"], correct:3, explanation:"Clay's large specific surface and net negative charge attract and hold exchangeable cations (Ca, Mg, K), giving a high CEC. Sandy soils, with low surface area, have low CEC." },
  { id:"gt13_037", qNo:37, subject:"soil-science", question:"The soil reaction (pH) range most favourable for the availability of the majority of plant nutrients is:", options:["3.5 to 4.5 (strongly acidic)", "8.5 to 9.5 (strongly alkaline)", "6.5 to 7.5 (near neutral)", "Below 3.0"], correct:2, explanation:"Most nutrients are maximally available near neutrality (pH 6.5–7.5). Strong acidity reduces availability of P, Ca, Mg and increases Al/Fe toxicity, while strong alkalinity reduces availability of P and micronutrients like Fe, Zn." },
  { id:"gt13_038", qNo:38, subject:"soil-fertility", question:"Symbiotic nitrogen fixation in pulse crops is carried out by bacteria of the genus:", options:["Azotobacter", "Azospirillum", "Nitrosomonas", "Rhizobium"], correct:3, explanation:"Rhizobium forms root nodules in legumes and fixes atmospheric N2 symbiotically. Azotobacter is free-living, Azospirillum is associative, and Nitrosomonas oxidises ammonia in nitrification (not fixation)." },
  { id:"gt13_039", qNo:39, subject:"soil-fertility", question:"Which of the following biofertilisers is a phosphate-solubilising microorganism?", options:["Rhizobium", "Azolla", "Phosphobacteria", "Azotobacter"], correct:2, explanation:"Phosphobacteria (phosphate-solubilising bacteria) convert fixed/insoluble soil phosphorus into plant-available forms. Rhizobium and Azotobacter are nitrogen fixers." },
  { id:"gt13_040", qNo:40, subject:"soil-fertility", question:"The nitrogen content of urea is approximately:", options:["18%", "82%", "26%", "46%"], correct:3, explanation:"Urea contains about 46% nitrogen — the highest among solid straight nitrogenous fertilisers. Single super phosphate (SSP, ~16% P2O5) is a phosphatic fertiliser, not nitrogenous." },
  { id:"gt13_041", qNo:41, subject:"farm-machinery", question:"The mould-board plough is classified as a primary tillage implement because it:", options:["Cuts and inverts the soil, burying weeds and residues", "Only levels the soil surface", "Sprays pesticides and applies fertiliser to the standing crop", "Is used only after sowing"], correct:0, explanation:"Primary tillage opens the soil with the first ploughing. The mould-board plough cuts and inverts the furrow slice, burying weeds and residues — which defines it as a primary tillage implement." },
  { id:"gt13_042", qNo:42, subject:"farm-machinery", question:"In a four-stroke internal combustion engine, the correct sequence of strokes is:", options:["Compression, suction, exhaust, power", "Power, exhaust, suction, compression", "Suction, power, compression, exhaust", "Suction, compression, power, exhaust"], correct:3, explanation:"A four-stroke cycle proceeds as Suction (intake) → Compression → Power (expansion/working) → Exhaust, completed in two revolutions of the crankshaft. Diesel tractor engines work on this cycle." },
  { id:"gt13_043", qNo:43, subject:"farm-machinery", question:"Which implement is used for secondary tillage / inter-cultivation (weeding)?", options:["Cultivator", "Seed drill", "Thresher", "Mould-board plough"], correct:0, explanation:"A cultivator is a secondary tillage implement used for inter-cultivation and weeding. The mould-board plough does primary tillage, the seed drill sows seed and the thresher threshes the crop." },
  { id:"gt13_044", qNo:44, subject:"farm-machinery", question:"Which of the following statements about farm power is/are correct?\n1. The power of a tractor engine is commonly expressed in horsepower (hp).\n2. The power take-off (PTO) transmits engine power to operate attached machines.\n3. A diesel engine works on the spark-ignition principle.", options:["2 and 3 only", "1 and 2 only", "1, 2 and 3", "1 and 3 only"], correct:1, explanation:"Statements 1 and 2 are correct. Statement 3 is FALSE — a diesel engine works on COMPRESSION ignition (not spark ignition; petrol engines use spark ignition). Hence 1 and 2 only." },
  { id:"gt13_045", qNo:45, subject:"farm-machinery", question:"The main advantage of using a tractor-drawn seed-cum-fertiliser drill over manual broadcasting is:", options:["It removes the need for irrigation", "Uniform seed depth, spacing and fertiliser placement", "It eliminates the need for land preparation", "It increases the seed rate required"], correct:1, explanation:"A seed-cum-fertiliser drill places seed at uniform depth and row spacing and bands fertiliser near the seed in one operation, improving germination, plant stand and fertiliser-use efficiency while saving labour and seed." },
  { id:"gt13_046", qNo:46, subject:"surveying", question:"The fundamental principle of chain (chain-and-tape) surveying is:", options:["Using only a magnetic compass to fix all stations", "Working from whole to part using triangulation", "Measuring only vertical distances", "Working from part to whole"], correct:1, explanation:"Chain surveying is based on triangulation — the area is divided into a network of well-conditioned triangles and the principle of 'working from whole to part' is followed to control the accumulation of errors." },
  { id:"gt13_047", qNo:47, subject:"surveying", question:"Assertion (A): In the whole-circle bearing (WCB) system, the bearing of a line can range from 0° to 360°.\nReason (R): The bearing is measured clockwise from the north end of the magnetic meridian.", options:["Both A and R are true, but R is NOT the correct explanation of A", "A is true but R is false", "Both A and R are true, and R is the correct explanation of A", "A is false but R is true"], correct:2, explanation:"In the WCB system the bearing is measured clockwise from the north of the meridian, so it can take any value from 0° to 360°. R correctly explains why A is true." },
  { id:"gt13_048", qNo:48, subject:"surveying", question:"If the fore bearing (FB) of a line AB is 60°, its back bearing (BB) is:", options:["60°", "300°", "240°", "120°"], correct:2, explanation:"Back bearing = fore bearing ± 180°. Since FB = 60° (< 180°), BB = 60° + 180° = 240°." },
  { id:"gt13_049", qNo:49, subject:"surveying", question:"Match List-I (Instrument) with List-II (Use):", matchTable:{ headers:["List-I (Instrument)", "List-II (Use)"], rows:[["A. Prismatic compass", "1. Measuring horizontal distances along a line"], ["B. Chain/tape", "2. Measuring horizontal angles/bearings"], ["C. Plane table", "3. Measuring horizontal and vertical angles"], ["D. Theodolite", "4. Plotting the survey in the field directly"]] }, options:["A-3, B-1, C-4, D-2", "A-2, B-4, C-1, D-3", "A-2, B-1, C-4, D-3", "A-1, B-2, C-3, D-4"], correct:2, explanation:"Prismatic compass = bearings (2); Chain/tape = measuring horizontal distance (1); Plane table = field plotting (4); Theodolite = horizontal & vertical angles (3). Hence A-2, B-1, C-4, D-3." },
  { id:"gt13_050", qNo:50, subject:"agricultural-economics", question:"The law of demand states that, other things remaining equal:", options:["Demand rises as price rises", "Demand is independent of price", "Price and quantity demanded always move in the same direction", "As price falls, quantity demanded rises (and vice versa)"], correct:3, explanation:"The law of demand expresses an inverse relationship between price and quantity demanded (ceteris paribus): as price falls, quantity demanded rises, and as price rises, quantity demanded falls. This gives the downward-sloping demand curve." },
  { id:"gt13_051", qNo:51, subject:"agricultural-economics", question:"The addition to total cost from producing one more unit of output is called:", options:["Opportunity cost", "Average cost", "Fixed cost", "Marginal cost"], correct:3, explanation:"Marginal cost is the addition to total cost when one more unit is produced. Fixed cost does not change with output in the short run; average cost is total cost per unit." },
  { id:"gt13_052", qNo:52, subject:"agricultural-economics", question:"As successive units of a variable input are added to a fixed input, total output eventually increases at a decreasing rate. This is the law of:", options:["Increasing returns", "Demand", "Diminishing marginal returns", "Constant returns"], correct:2, explanation:"The law of diminishing marginal returns states that beyond a point, additional units of a variable input give smaller and smaller additions to output (a declining marginal product)." },
  { id:"gt13_053", qNo:53, subject:"agricultural-economics", question:"As the number of middlemen in a marketing channel increases, the producer's share in the consumer's rupee generally:", options:["Decreases", "Increases", "Becomes zero", "Stays the same"], correct:0, explanation:"More intermediaries add margins and costs, so the producer's share in the consumer's rupee decreases. Cooperative marketing reduces middlemen to improve the price realised by farmers." },
  { id:"gt13_054", qNo:54, subject:"agricultural-economics", question:"In economics, 'elasticity of demand' measures the:", options:["Responsiveness of quantity demanded to a price change", "Total quantity demanded by all buyers at a given price", "Cost of production per unit", "Government-fixed price of a commodity"], correct:0, explanation:"Price elasticity of demand is the responsiveness of quantity demanded to a change in price = (% change in quantity demanded) ÷ (% change in price). Most farm products (necessities) tend to be price-inelastic." },
  { id:"gt13_055", qNo:55, subject:"extension", question:"The 'Training and Visit (T&V)' system of agricultural extension is characterised by:", options:["Radio broadcasts as the sole method", "Regular worker training and a fixed visit schedule to contact farmers", "Occasional random visits to farmers without any fixed schedule", "Distribution of free inputs only"], correct:1, explanation:"The T&V system (introduced by Daniel Benor) is built on regular fortnightly training of village extension workers and a fixed schedule of visits to contact farmers, ensuring a continuous flow of recommendations from research to farmers." },
  { id:"gt13_056", qNo:56, subject:"extension", question:"The Community Development Programme (CDP) in India was launched in the year:", options:["1952", "1966", "1947", "1974"], correct:0, explanation:"The Community Development Programme was launched on 2 October 1952 for all-round rural development. The T&V system came in the 1970s and ATMA is a later decentralised model." },
  { id:"gt13_057", qNo:57, subject:"extension", question:"Which extension teaching method is based mainly on the principle of 'seeing is believing'?", options:["Circular letter", "Radio talk", "Lecture method", "Result demonstration"], correct:3, explanation:"A result demonstration shows the advantage of an improved practice in the farmer's own field, convincing farmers on the 'seeing is believing' principle. It is among the most effective extension methods." },
  { id:"gt13_058", qNo:58, subject:"extension", question:"The concept of the 'Extension Education Process' — teaching taking place step-wise in a cyclic manner — was developed by:", options:["Daniel Benor", "Norman Borlaug", "Dr. J. Paul Leagans", "M.S. Swaminathan"], correct:2, explanation:"Dr. J. Paul Leagans developed the concept of the Extension Education Process, under which extension teaching happens step-wise in a cyclic manner starting with a study of the situation. Daniel Benor, in contrast, designed the Training & Visit (T&V) system." },
  { id:"gt13_059", qNo:59, subject:"extension", question:"Agricultural extension is best described as:", options:["Formal classroom degree education", "A government scheme that only distributes subsidies and free inputs", "Non-formal education helping rural people decide for themselves", "Compulsory licensing of farmers"], correct:2, explanation:"Extension is an out-of-school, non-formal education for rural people that helps them make their own decisions (self-help) and improve their farming and standard of living." },
  { id:"gt13_060", qNo:60, subject:"agronomy", question:"Green manuring with a legume such as Sesbania mainly benefits the soil by:", options:["Removing all soil microbes", "Increasing soil salinity", "Raising the soil pH above 9 within a season", "Adding organic matter and fixed nitrogen"], correct:3, explanation:"Green-manure legumes (Sesbania, Sunhemp) grown and ploughed in while green add organic matter and biologically fixed nitrogen and improve the soil's physical condition." },
  { id:"gt13_061", qNo:61, subject:"horticulture", question:"The edible fruit of mango is botanically classified as a:", options:["Pome", "Berry", "Drupe", "Hesperidium"], correct:2, explanation:"Mango is a drupe — a fleshy fruit with an outer skin (exocarp), a fleshy edible mesocarp and a hard stony endocarp (stone) enclosing the seed. A hesperidium is the citrus fruit type and a pome is the apple type." },
  { id:"gt13_062", qNo:62, subject:"horticulture", question:"Match List-I (Fruit crop) with List-II (Family):", matchTable:{ headers:["List-I (Fruit)", "List-II (Family)"], rows:[["A. Citrus", "1. Musaceae"], ["B. Banana", "2. Caricaceae"], ["C. Papaya", "3. Rutaceae"], ["D. Grape", "4. Vitaceae"]] }, options:["A-3, B-2, C-1, D-4", "A-3, B-1, C-2, D-4", "A-1, B-3, C-2, D-4", "A-2, B-1, C-3, D-4"], correct:1, explanation:"Citrus = Rutaceae (3); Banana = Musaceae (1); Papaya = Caricaceae (2); Grape = Vitaceae (4). Hence A-3, B-1, C-2, D-4." },
  { id:"gt13_063", qNo:63, subject:"horticulture", question:"Cultivated banana is propagated vegetatively by suckers mainly because it is:", options:["A biennial crop", "Parthenocarpic and seedless", "A grafted crop", "Grown only from seed"], correct:1, explanation:"Cultivated banana sets fruit parthenocarpically and is seedless, so it cannot be raised from seed; it is multiplied vegetatively by suckers (or by tissue culture)." },
  { id:"gt13_064", qNo:64, subject:"horticulture", question:"Which of the following is a cool-season (winter) vegetable?", options:["Cluster bean", "Cabbage", "Brinjal", "Bhendi (okra)"], correct:1, explanation:"Cabbage is a cool-season crucifer that needs low temperatures for good head formation. Brinjal, okra and cluster bean are warm-season vegetables." },
  { id:"gt13_065", qNo:65, subject:"horticulture", question:"The edible part of cauliflower is the:", options:["Immature fruit", "Curd (compact flower head)", "Bulb", "Modified root"], correct:1, explanation:"In cauliflower the edible part is the 'curd' — a compact, immature flower head. Carrot's edible part is a modified root and onion's is a bulb." },
  { id:"gt13_066", qNo:66, subject:"horticulture", question:"Which of the following statements about horticulture is/are correct?\n1. Marigold is an important loose-flower (ornamental) crop.\n2. Tomato is rich in the antioxidant lycopene.\n3. Pomegranate is a temperate fruit that needs chilling and snow.", options:["1, 2 and 3", "2 and 3 only", "1 and 3 only", "1 and 2 only"], correct:3, explanation:"Statements 1 and 2 are correct. Statement 3 is FALSE — pomegranate is a subtropical/arid-zone fruit, not a temperate crop needing chilling. Hence 1 and 2 only." },
  { id:"gt13_067", qNo:67, subject:"horticulture", question:"The horticultural practice of removing unwanted/dead/diseased plant parts to improve form and yield is called:", options:["Budding", "Ringing", "Layering", "Pruning"], correct:3, explanation:"Pruning is the judicious removal of plant parts (dead, diseased or crowded shoots) to regulate growth, improve light penetration and increase fruiting. Layering and budding are propagation methods." },
  { id:"gt13_068", qNo:68, subject:"forestry", question:"Agroforestry is best defined as a land-use system in which:", options:["Only timber trees are grown in rows for commercial harvesting", "Trees/shrubs are grown together with crops and/or livestock on the same land", "Crops are grown only inside a climate-controlled greenhouse", "Forests are cleared for permanent cropping"], correct:1, explanation:"Agroforestry deliberately integrates woody perennials (trees/shrubs) with agricultural crops and/or livestock on the same land, in space or time, to obtain multiple products and ecological benefits." },
  { id:"gt13_069", qNo:69, subject:"forestry", question:"Match List-I (Medicinal/aromatic plant) with List-II (Use/part):", matchTable:{ headers:["List-I (Plant)", "List-II (Use/part)"], rows:[["A. Ashwagandha", "1. Aromatic oil from leaves (lemon scent)"], ["B. Lemon grass", "2. Roots used as a tonic/adaptogen"], ["C. Aloe vera", "3. Aromatic oil (rose-scented geranium)"], ["D. Geranium", "4. Leaf gel used in cosmetics & medicine"]] }, options:["A-2, B-4, C-1, D-3", "A-3, B-1, C-4, D-2", "A-1, B-2, C-4, D-3", "A-2, B-1, C-4, D-3"], correct:3, explanation:"Ashwagandha = roots used as tonic/adaptogen (2); Lemon grass = aromatic lemon-scented oil from leaves (1); Aloe vera = leaf gel for cosmetics/medicine (4); Geranium = rose-scented aromatic oil (3). Hence A-2, B-1, C-4, D-3." },
  { id:"gt13_070", qNo:70, subject:"forestry", question:"Assertion (A): Social forestry was promoted to raise trees on community and wastelands.\nReason (R): It aims to meet the fuelwood, fodder and small-timber needs of rural people and reduce pressure on natural forests.", options:["Both A and R are true, but R is NOT the correct explanation of A", "A is true but R is false", "Both A and R are true, and R is the correct explanation of A", "A is false but R is true"], correct:2, explanation:"Social forestry raises trees on community lands, wastelands and along roads/canals specifically to supply rural fuelwood, fodder and small timber and to relieve pressure on natural forests. R correctly explains A." },
  { id:"gt13_071", qNo:71, subject:"forestry", question:"The branch of forestry that deals with the development and care of forests — raising, tending and reproduction of forest crops — is called:", options:["Agronomy", "Sericulture", "Silviculture", "Dendrology"], correct:2, explanation:"Silviculture is the theory and practice of raising, tending and regenerating forest crops. (Dendrology is the study/identification of trees; sericulture is silkworm rearing.)" },
  { id:"gt13_072", qNo:72, subject:"forestry", question:"Shifting cultivation (jhum / podu) is a practice that involves:", options:["Clearing and burning a forest patch for temporary cropping", "Hydroponic cultivation", "Permanent terraced farming", "Growing only timber trees in straight rows on cleared land"], correct:0, explanation:"Shifting cultivation clears and burns a forest patch, crops it for a few years and then abandons it for a fresh patch. (Teak, by contrast, is a high-value hardwood, not a softwood.)" },
  { id:"gt13_073", qNo:73, subject:"seed-technology", question:"In a seed germination test, the result is normally expressed as the percentage of:", options:["Seeds that produce normal seedlings in the test", "Seeds heavier than the average", "Seeds infected by fungi", "Seeds that are physically pure and free of inert matter"], correct:0, explanation:"Germination percentage is the proportion of pure seeds that produce NORMAL seedlings under optimum (favourable) test conditions in a stipulated period. It is a key quality parameter for seed certification." },
  { id:"gt13_074", qNo:74, subject:"seed-technology", question:"In the Indian seed-certification colour code, certified seed carries a tag of which colour?", options:["Blue", "Golden yellow", "White", "Green"], correct:0, explanation:"Tag colour code: breeder seed = golden yellow, foundation seed = white, certified seed = blue." },
  { id:"gt13_075", qNo:75, subject:"seed-technology", question:"Seed dormancy is best described as a condition in which:", options:["Viable seeds fail to germinate even under favourable conditions for a period", "Seeds float on water", "Seeds germinate immediately after shedding even if conditions are poor", "Seeds lose viability permanently"], correct:0, explanation:"Dormancy is a state in which viable seeds fail to germinate even when conditions (moisture, temperature, aeration) are favourable. It can be broken by treatments such as scarification, chilling or chemical (e.g., nitric acid) treatment." },
  { id:"gt13_076", qNo:76, subject:"genetics", question:"The hereditary material in most organisms, carrying genetic information, is:", options:["Protein made of amino-acid chains", "Lipid", "Starch", "DNA (deoxyribonucleic acid)"], correct:3, explanation:"DNA is the hereditary material in most organisms; genes are segments of DNA. (Some viruses use RNA as their genetic material.) The double-helix structure was described by Watson and Crick." },
  { id:"gt13_077", qNo:77, subject:"genetics", question:"Who is regarded as the 'Father of Genetics'?", options:["Watson & Crick", "Gregor Mendel", "T.H. Morgan", "Charles Darwin"], correct:1, explanation:"Gregor Mendel is the Father of Genetics for his laws of inheritance. Watson & Crick described the DNA double helix, Morgan worked on linkage in Drosophila and Darwin proposed natural selection." },
  { id:"gt13_078", qNo:78, subject:"crop-pests", question:"The pulse beetle (Callosobruchus) that bores into stored pulses such as greengram and redgram is a serious pest of:", options:["Stored grain/pulses in godowns", "Fruit orchards", "Forest timber", "Standing field crop only"], correct:0, explanation:"The pulse beetle (Callosobruchus chinensis/maculatus) is a major STORAGE pest; grubs develop inside the seed, causing characteristic exit holes and heavy weight loss in stored pulses. Management includes proper drying, hermetic storage and fumigation." },
  { id:"gt13_079", qNo:79, subject:"surveying", question:"In levelling, a 'bench mark' (BM) is a:", options:["Line joining two survey stations", "Temporary peg of unknown height", "Horizontal angle measured from north", "Fixed point of known elevation above the datum"], correct:3, explanation:"A bench mark is a fixed point of known and permanent elevation referred to an assumed or mean-sea-level datum; it is used as a reference to determine the reduced levels of other points in levelling." },
  { id:"gt13_080", qNo:80, subject:"kharif-crops", question:"Pearl millet (bajra), one of the most drought-hardy cereals, is best suited to:", options:["Light sandy soils of hot arid regions", "Waterlogged heavy clay soils", "Saline coastal marshes", "Cold temperate hills"], correct:0, explanation:"Pearl millet tolerates drought and heat and grows well on light, well-drained sandy soils in hot, low-rainfall arid and semi-arid regions where other cereals fail. It is rich in iron and zinc." },
  { id:"gt13_081", qNo:81, subject:"general-agriculture", question:"The Indian Council of Agricultural Research (ICAR), the apex body for coordinating agricultural research in India, has its headquarters at:", options:["Pune", "New Delhi", "Hyderabad", "Bengaluru"], correct:1, explanation:"ICAR (established 1929) is headquartered at New Delhi (Krishi Bhavan) and functions under the Department of Agricultural Research and Education (DARE). It coordinates research and education across the national agricultural system." },
  { id:"gt13_082", qNo:82, subject:"general-agriculture", question:"Match List-I (Research institute) with List-II (Location):", matchTable:{ headers:["List-I (Institute)", "List-II (Location)"], rows:[["A. Central Rice Research Institute", "1. Nagpur"], ["B. Indian Agricultural Research Institute", "2. Cuttack"], ["C. Central Institute for Cotton Research", "3. Bengaluru"], ["D. Indian Institute of Horticultural Research", "4. New Delhi"]] }, options:["A-2, B-4, C-1, D-3", "A-4, B-2, C-1, D-3", "A-1, B-4, C-2, D-3", "A-2, B-1, C-4, D-3"], correct:0, explanation:"CRRI = Cuttack (2); IARI (Pusa) = New Delhi (4); CICR = Nagpur (1); IIHR = Bengaluru (3). Hence A-2, B-4, C-1, D-3." },
  { id:"gt13_083", qNo:83, subject:"general-agriculture", question:"Match List-I (Revolution) with List-II (Associated product):", matchTable:{ headers:["List-I (Revolution)", "List-II (Product)"], rows:[["A. Green Revolution", "1. Milk"], ["B. White Revolution", "2. Fish"], ["C. Blue Revolution", "3. Food grains"], ["D. Yellow Revolution", "4. Oilseeds"]] }, options:["A-3, B-1, C-2, D-4", "A-4, B-1, C-2, D-3", "A-1, B-3, C-2, D-4", "A-3, B-2, C-1, D-4"], correct:0, explanation:"Green = food grains (3); White (Operation Flood) = milk (1); Blue = fish/aquaculture (2); Yellow = oilseeds (4). Hence A-3, B-1, C-2, D-4." },
  { id:"gt13_084", qNo:84, subject:"general-agriculture", question:"Assertion (A): Norman Borlaug is regarded as the 'Father of the Green Revolution'.\nReason (R): He developed high-yielding semi-dwarf wheat varieties that greatly increased food-grain production.", options:["A is false but R is true", "Both A and R are true, and R is the correct explanation of A", "A is true but R is false", "Both A and R are true, but R is NOT the correct explanation of A"], correct:1, explanation:"Norman Borlaug developed high-yielding, fertiliser-responsive semi-dwarf wheats that dramatically raised yields, earning him the title 'Father of the Green Revolution' (Nobel Peace Prize 1970). In India, M.S. Swaminathan led the movement. R correctly explains A." },
  { id:"gt13_085", qNo:85, subject:"general-agriculture", question:"India holds the FIRST rank in the world in the production of:", options:["Wheat", "Soybean", "Milk", "Maize"], correct:2, explanation:"India is the world's largest producer of milk (since Operation Flood / White Revolution) and also leads in pulses, jute and several spices. It is the second-largest producer of wheat and rice." },
  { id:"gt13_086", qNo:86, subject:"general-agriculture", question:"Which of the following statements is/are correct?\n1. PJTSAU (the State Agricultural University of Telangana) is headquartered at Rajendranagar, Hyderabad.\n2. A Kisan Credit Card (KCC) provides short-term crop loans to farmers.\n3. The Soil Health Card scheme discourages soil testing.", options:["1 and 2 only", "1, 2 and 3", "2 and 3 only", "1 and 3 only"], correct:0, explanation:"Statements 1 and 2 are correct. Statement 3 is FALSE — the Soil Health Card scheme PROMOTES soil testing and provides nutrient recommendations to farmers. Hence 1 and 2 only." },
  { id:"gt13_087", qNo:87, subject:"general-agriculture", question:"In modern agriculture, the use of drones (UAVs) is increasingly adopted mainly for:", options:["Replacing soil entirely", "Generating electricity to run village irrigation pumps", "Aerial spraying of inputs and crop health monitoring", "Permanent storage of grain"], correct:2, explanation:"Agricultural drones are used for aerial spraying of pesticides and nutrients, crop and field monitoring (with multispectral imaging), and assessing crop health/stress — key tools of precision farming." },
  { id:"gt13_088", qNo:88, subject:"general-agriculture", question:"The technique of applying water directly to the root zone drop by drop through a network of pipes and emitters, giving very high water-use efficiency, is:", options:["Drip (trickle) irrigation", "Furrow irrigation", "Basin irrigation", "Flood irrigation"], correct:0, explanation:"Drip irrigation delivers water slowly to the root zone through emitters, minimising evaporation and percolation losses and giving the highest water-use efficiency (often 90%+). It also enables fertigation." },
  { id:"gt13_089", qNo:89, subject:"soil-science", question:"Which of the following is NOT one of the soil-forming factors?", options:["Living organisms", "Wind speed of jet streams", "Parent material", "Climate"], correct:1, explanation:"The five soil-forming factors are Climate, Organisms, Relief (topography), Parent material and Time (ClORPT). Upper-atmosphere jet-stream wind speed is not a recognised soil-forming factor." },
  { id:"gt13_090", qNo:90, subject:"soil-science", question:"Assertion (A): Saline soils can be reclaimed by leaching with good-quality water and providing adequate drainage.\nReason (R): Saline soils contain excess soluble salts that must be washed below the root zone and removed.", options:["A is true but R is false", "Both A and R are true, but R is NOT the correct explanation of A", "A is false but R is true", "Both A and R are true, and R is the correct explanation of A"], correct:3, explanation:"Saline soils have excess soluble salts; leaching with good water dissolves and moves the salts below the root zone, and drainage removes them. This is why leaching + drainage reclaims saline soils. R correctly explains A. (Alkali/sodic soils additionally need gypsum.)" },
  { id:"gt13_091", qNo:91, subject:"soil-science", question:"A soil that contains a balanced mixture of sand, silt and clay and is ideal for most crops is called:", options:["Pure clay", "Gravel", "Loam", "Pure sand"], correct:2, explanation:"Loam is a textural class with a balanced proportion of sand, silt and clay. It combines good drainage and aeration with adequate water- and nutrient-holding capacity, making it ideal for most crops." },
  { id:"gt13_092", qNo:92, subject:"soil-fertility", question:"The three primary (macro) nutrients required by plants in the largest amounts are:", options:["Nitrogen, phosphorus and potassium", "Iron, zinc and manganese", "Calcium, magnesium and sulphur", "Boron, copper and molybdenum"], correct:0, explanation:"The primary macronutrients are Nitrogen (N), Phosphorus (P) and Potassium (K) — needed in the largest quantities. Ca, Mg, S are secondary nutrients; Fe, Zn, Mn, B, Cu, Mo, Cl are micronutrients." },
  { id:"gt13_093", qNo:93, subject:"soil-fertility", question:"Match List-I (Nutrient) with List-II (Deficiency symptom):", matchTable:{ headers:["List-I (Nutrient)", "List-II (Deficiency symptom)"], rows:[["A. Nitrogen", "1. Interveinal chlorosis of young leaves"], ["B. Phosphorus", "2. General yellowing (chlorosis) of older leaves"], ["C. Potassium", "3. Purplish-red colouration of leaves/stem"], ["D. Iron", "4. Scorching/drying of leaf margins"]] }, options:["A-1, B-3, C-4, D-2", "A-3, B-2, C-4, D-1", "A-2, B-3, C-4, D-1", "A-2, B-4, C-3, D-1"], correct:2, explanation:"Nitrogen = general yellowing of older leaves (2); Phosphorus = purpling of leaves/stem (3); Potassium = marginal scorching/drying (4); Iron = interveinal chlorosis of young leaves (1). Hence A-2, B-3, C-4, D-1." },
  { id:"gt13_094", qNo:94, subject:"soil-fertility", question:"Which of the following statements is/are correct?\n1. Nitrogen is a mobile nutrient, so its deficiency appears first in older leaves.\n2. Vermicompost is produced by earthworms decomposing organic waste.\n3. Gypsum is used to reclaim acidic soils.", options:["1 and 3 only", "1, 2 and 3", "2 and 3 only", "1 and 2 only"], correct:3, explanation:"Statements 1 and 2 are correct. Statement 3 is FALSE — gypsum (CaSO4) is used to reclaim ALKALI (sodic) soils, not acidic soils; acidic soils are corrected with lime. Hence 1 and 2 only." },
  { id:"gt13_095", qNo:95, subject:"english", question:"Choose the word that is the ANTONYM (opposite) of 'ABUNDANT':", options:["Plentiful", "Sufficient", "Ample", "Scarce"], correct:3, explanation:"'Abundant' means existing in large quantity. Its opposite is 'scarce' (insufficient/in short supply). Plentiful, ample and sufficient are synonyms of abundant." },
  { id:"gt13_096", qNo:96, subject:"english", question:"Change the following sentence into the passive voice: 'The farmer harvests the crop.'", options:["The farmer is harvested by the crop", "The crop has harvested the farmer", "The crop is harvested by the farmer", "The crop was harvested by the farmer"], correct:2, explanation:"In the simple present passive, 'harvests' (active) becomes 'is harvested' and the object 'the crop' becomes the subject: 'The crop is harvested by the farmer.'" },
  { id:"gt13_097", qNo:97, subject:"english", question:"Fill in the blank with the correct preposition: 'The seeds were sown ___ the month of June.'", options:["at", "since", "in", "on"], correct:2, explanation:"The preposition 'in' is used with months, years and seasons — 'in the month of June'. ('On' is used with dates/days and 'at' with clock time.)" },
  { id:"gt13_098", qNo:98, subject:"computer-applications", question:"In computer memory, one byte is equal to:", options:["4 bits", "8 bits", "16 bits", "1024 bits"], correct:1, explanation:"One byte = 8 bits. Higher units: 1 Kilobyte (KB) = 1024 bytes, 1 Megabyte (MB) = 1024 KB, 1 Gigabyte (GB) = 1024 MB." },
  { id:"gt13_099", qNo:99, subject:"computer-applications", question:"Which Microsoft Office application is primarily used for creating spreadsheets and performing calculations?", options:["MS Access", "MS Word", "MS PowerPoint", "MS Excel"], correct:3, explanation:"MS Excel is the spreadsheet program used for tabular data, formulas, functions and charts (files saved as .xlsx). Word is for documents, PowerPoint for presentations and Access for databases." },
  { id:"gt13_100", qNo:100, subject:"rabi-crops", question:"Among rabi oilseeds, the crop whose flowers and leaves bear spines and which is valued for its quality edible oil and carthamin dye is:", options:["Sunflower", "Safflower (kusum)", "Linseed", "Niger"], correct:1, explanation:"Safflower (Carthamus tinctorius) is a spiny rabi oilseed grown on conserved soil moisture; its seed yields good-quality edible oil (rich in linoleic acid) and the florets give the carthamin dye. It is hardy and drought tolerant." },
];
